def investigate(context, acquire):
    committed = {}
    main_state = None
    other_state = None
    main_changes = 0
    other_changes = 0
    actions = context["actions"]
    for action in actions:
        op = action["op"]
        conn = action.get("connection", "main")
        if op == "begin":
            if conn == "main":
                main_state = dict(committed)
            else:
                other_state = dict(committed)
        elif op == "commit":
            if conn == "main":
                if main_state is not None:
                    committed = main_state
                    main_state = None
            else:
                if other_state is not None:
                    committed = other_state
                    other_state = None
        elif op == "rollback":
            if conn == "main":
                main_state = None
            else:
                other_state = None
        elif op == "put":
            key = action["key"]
            value = action["value"]
            if conn == "main":
                state = main_state if main_state is not None else committed
                if key not in state:
                    state[key] = value
                    main_changes += 1
            else:
                state = other_state if other_state is not None else committed
                if key not in state:
                    state[key] = value
                    other_changes += 1
        elif op == "update":
            key = action["key"]
            value = action["value"]
            if conn == "main":
                state = main_state if main_state is not None else committed
                if key in state:
                    state[key] = value
                    main_changes += 1
            else:
                state = other_state if other_state is not None else committed
                if key in state:
                    state[key] = value
                    other_changes += 1
        elif op == "delete":
            key = action["key"]
            if conn == "main":
                state = main_state if main_state is not None else committed
                if key in state:
                    state.pop(key)
                    main_changes += 1
            else:
                state = other_state if other_state is not None else committed
                if key in state:
                    state.pop(key)
                    other_changes += 1
    goal = context["goal"]
    if goal == "channel":
        value = main_changes + other_changes
    elif goal == "committed_count":
        value = len(committed)
    elif goal == "committed_sum":
        value = sum(committed.values())
    else:
        return {"value": None, "unresolved": True}
    return {"value": value, "unresolved": False}

